import { router, useLocalSearchParams } from 'expo-router';
import { StatusBar } from 'expo-status-bar';
import { useEffect, useRef, useState } from 'react';
import { ActivityIndicator, Linking, Pressable, StyleSheet, Text, View } from 'react-native';
import Animated, { useReducedMotion } from 'react-native-reanimated';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import Svg, { Path } from 'react-native-svg';

import { animate, FADE, rise } from '@/components/today/motion';
import { VoiceOrb } from '@/components/voice-orb';
import { VoiceTranscript } from '@/components/voice-transcript';
import { BrandColors, BrandFonts } from '@/constants/theme';
import { useVoiceAgent } from '@/hooks/use-voice-agent';
import { saveConversation } from '@/lib/conversations';
import { canSaveTranscript, dreamTextFromTranscript } from '@/lib/deepgram/conversation';
import type { DreamContext } from '@/lib/deepgram/types';
import { isLiveStatus, statusLabel } from '@/lib/deepgram/voice-state';
import { analyzeDream, createDream, fetchDreamById } from '@/services/dreams';
import type { Dream } from '@/types/dream';
import { getErrorMessage } from '@/utils/errors';

/** What the screen is doing with the conversation once the talking has stopped. */
type SaveStep = 'none' | 'saving' | 'reflecting';

const SAVE_LABELS: Record<Exclude<SaveStep, 'none'>, string> = {
  saving: 'keeping your dream…',
  reflecting: 'reading your dream…',
};

/** Lets the screen finish sliding in before the microphone opens. */
const AUTOSTART_DELAY_MS = 450;

/**
 * Voice companion screen ("/voice"). Real-time conversation with the Deepgram Voice Agent.
 * Needs the native development build.
 *
 * Params:
 * - `dreamId` — talk about a dream that is already saved. Never creates a second one.
 * - `autostart` — connect as soon as the screen opens (home's yap button does this),
 *   so the companion is already asking by the time the screen has settled.
 *
 * Telling a new dream: when the conversation ends, their own words are saved as the dream,
 * the whole back-and-forth is kept on the phone for the transcript tab, `analyze-dream` is
 * asked for the reading, and the Dream screen opens on it — the same place a written or
 * yapped dream lands, so everything after this point is the normal flow.
 */
export default function VoiceScreen() {
  const { dreamId, autostart } = useLocalSearchParams<{ dreamId?: string; autostart?: string }>();
  const insets = useSafeAreaInsets();
  const reduceMotion = useReducedMotion();
  const { dream, loadingDream } = useDreamContext(dreamId);
  const { state, inputLevel, outputLevel, start, end, toggleMute } = useVoiceAgent(dream);
  const [saveStep, setSaveStep] = useState<SaveStep>('none');
  const [saveError, setSaveError] = useState<string | null>(null);

  const live = isLiveStatus(state.status);
  const busy = live || state.status === 'connecting';
  const saving = saveStep !== 'none';
  // Only a dream being told for the first time is worth saving, and only once they said enough.
  const canSave = !dreamId && canSaveTranscript(state.transcript);
  const canStart = !busy && !saving && !loadingDream && state.error?.kind !== 'unsupported';

  // Opened from home's yap button: connect on our own, once (re-tapping start is still theirs).
  const started = useRef(false);
  useEffect(() => {
    if (autostart !== '1' || started.current || loadingDream) return;
    started.current = true;
    const timer = setTimeout(start, AUTOSTART_DELAY_MS);
    return () => clearTimeout(timer);
    // `start` changes identity with the loaded dream; only the first chance to run counts.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [autostart, loadingDream]);

  /** Saves what they told the companion, asks for the reading, then opens the dream. */
  async function saveDream() {
    setSaveError(null);
    setSaveStep('saving');

    // 1. Save the dream in their own words. If this fails, the transcript stays on screen
    //    so nothing they said is lost and they can try again.
    let saved: Dream;
    try {
      saved = await createDream(dreamTextFromTranscript(state.transcript));
    } catch (error) {
      setSaveError(getErrorMessage(error));
      setSaveStep('none');
      return;
    }

    // 2. Keep the conversation itself on the phone, so the Dream screen's transcript tab
    //    can show what the companion asked as well as what they answered.
    saveConversation(saved.id, state.transcript);

    // 3. Ask for the reading. If this fails the dream is still saved, and the Dream
    //    screen shows its own "try again".
    setSaveStep('reflecting');
    try {
      await analyzeDream(saved.id);
    } catch (error) {
      console.warn('AI reflection failed:', getErrorMessage(error));
    }

    // 4. Open it on the analysis tab. `replace` so "back" doesn't return to the call.
    router.replace({ pathname: '/dream/[id]', params: { id: saved.id, tab: 'analysis' } });
  }

  /** Ends the call, then turns it into a dream when there is one worth keeping. */
  function handleEnd() {
    end();
    if (canSave) void saveDream();
  }

  function handleClose() {
    // Don't walk out halfway through saving; the dream would be left without its reading.
    if (saving) return;
    end();
    if (router.canGoBack()) router.back();
    else router.replace('/home');
  }

  const label = loadingDream ? 'finding your dream…' : saving ? SAVE_LABELS[saveStep as 'saving'] : statusLabel(state);

  return (
    <View style={[styles.screen, { paddingTop: insets.top }]}>
      <StatusBar style="light" />

      <View style={styles.topBar}>
        <Pressable
          accessibilityRole="button"
          accessibilityLabel="Close"
          accessibilityState={{ disabled: saving }}
          disabled={saving}
          hitSlop={8}
          onPress={handleClose}
          style={({ pressed }) => [styles.round, pressed && styles.pressed, saving && styles.dim]}>
          <Svg width={9} height={16} viewBox="0 0 9 16">
            <Path d="M7.5 1.5L1.5 8l6 6.5" stroke="#fff" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" fill="none" />
          </Svg>
        </Pressable>
        <View style={styles.titleWrap}>
          <Text style={styles.title}>dream companion</Text>
          {!!dream?.title && (
            <Text style={styles.subtitle} numberOfLines={1}>
              {dream.title.toLowerCase()}
            </Text>
          )}
        </View>
        <View style={styles.round} />
      </View>

      <Pressable
        style={styles.orbArea}
        onPress={canStart ? start : undefined}
        accessibilityRole="button"
        accessibilityLabel={canStart ? 'Start the conversation' : statusLabel(state)}>
        <VoiceOrb status={state.status} muted={state.muted} inputLevel={inputLevel} outputLevel={outputLevel} size={150} />
        <View style={styles.statusRow}>
          {(state.status === 'connecting' || saving) && <ActivityIndicator color={BrandColors.lime} />}
          <Text style={[styles.status, state.status === 'error' && styles.statusError]} accessibilityLiveRegion="polite">
            {label}
          </Text>
        </View>
        {!!saveError && <Text style={[styles.hint, styles.hintError]}>{saveError}</Text>}
        {state.status === 'idle' && !loadingDream && (
          <Animated.Text style={[styles.hint, animate(reduceMotion, { animationName: FADE, animationDuration: 600 })]}>
            {dream ? 'talk it through out loud. you can interrupt anytime.' : 'tell your companion about a dream, out loud.'}
          </Animated.Text>
        )}
      </Pressable>

      <Animated.View style={[styles.transcript, rise(reduceMotion, 120)]}>
        <VoiceTranscript entries={state.transcript} live={live} />
      </Animated.View>

      <View style={[styles.controls, { paddingBottom: Math.max(insets.bottom, 16) }]}>
        {saving ? (
          <ControlButton label={SAVE_LABELS[saveStep as 'saving']} onPress={() => {}} disabled wide />
        ) : busy ? (
          <>
            <ControlButton
              label={state.muted ? 'unmute' : 'mute'}
              onPress={toggleMute}
              disabled={!live}
              variant={state.muted ? 'active' : 'plain'}
            />
            <ControlButton label={canSave ? 'done — interpret it' : 'end'} onPress={handleEnd} variant="primary" wide />
          </>
        ) : state.error?.kind === 'unsupported' ? (
          <ControlButton label="back" onPress={handleClose} wide />
        ) : state.error?.kind === 'permission' ? (
          <>
            <ControlButton label="open settings" onPress={() => Linking.openSettings()} />
            <ControlButton label="try again" onPress={start} variant="primary" wide />
          </>
        ) : (
          <>
            {/* The call dropped, or saving failed: their dream is still here to keep. */}
            {canSave && (
              <ControlButton label={saveError ? 'try keeping it again' : 'interpret it'} onPress={saveDream} variant="primary" wide />
            )}
            <ControlButton
              label={
                state.status === 'error'
                  ? state.transcript.length > 0
                    ? 'reconnect'
                    : 'try again'
                  : state.status === 'ended'
                    ? canSave
                      ? 'keep talking'
                      : 'start again'
                    : 'start talking'
              }
              onPress={start}
              disabled={!canStart}
              variant={canSave ? 'plain' : 'primary'}
              wide={!canSave}
            />
          </>
        )}
      </View>
    </View>
  );
}

/** Loads the selected dream (only the fields the companion needs), if one was passed. */
function useDreamContext(dreamId: string | undefined) {
  const [dream, setDream] = useState<DreamContext | null>(null);
  const [loadingDream, setLoadingDream] = useState(!!dreamId);

  useEffect(() => {
    if (!dreamId) return;
    let active = true;
    fetchDreamById(dreamId)
      .then((row) => {
        if (!active || !row) return;
        setDream({
          dreamText: row.dream_text,
          title: row.title,
          mood: row.mood,
          themes: row.themes,
          summary: row.summary,
        });
      })
      .catch((error) => console.warn('Could not load dream for the voice companion:', error))
      // If it fails, the companion still works; it just starts without the dream.
      .finally(() => {
        if (active) setLoadingDream(false);
      });
    return () => {
      active = false;
    };
  }, [dreamId]);

  return { dream, loadingDream };
}

type ControlButtonProps = {
  label: string;
  onPress: () => void;
  variant?: 'plain' | 'primary' | 'active';
  disabled?: boolean;
  wide?: boolean;
};

function ControlButton({ label, onPress, variant = 'plain', disabled = false, wide = false }: ControlButtonProps) {
  const filled = variant === 'primary' || variant === 'active';
  return (
    <Pressable
      accessibilityRole="button"
      accessibilityState={{ disabled }}
      onPress={onPress}
      disabled={disabled}
      style={({ pressed }) => [
        styles.button,
        wide && styles.buttonWide,
        variant === 'primary' && styles.buttonPrimary,
        variant === 'active' && styles.buttonActive,
        pressed && styles.pressed,
        disabled && styles.dim,
      ]}>
      <Text style={[styles.buttonText, filled && styles.buttonTextFilled]}>{label}</Text>
    </Pressable>
  );
}

const styles = StyleSheet.create({
  screen: {
    flex: 1,
    backgroundColor: '#000',
  },
  topBar: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 12,
    paddingHorizontal: 16,
    paddingVertical: 10,
  },
  round: {
    width: 38,
