import { useEffect, useRef, useState } from 'react';
import { StyleSheet, View } from 'react-native';
import Animated from 'react-native-reanimated';

import { ease } from '@/components/today/motion';
import { BrandFonts } from '@/constants/theme';

/** How long each word waits before it lights up (the design's pacing). */
const AFTERDREAM_MS = 210;
const YOU_MS = 290;

/** Height of the caption block, from the design. Two lines of 23/1.25 plus the speaker label. */
export const CAPTION_HEIGHT = 128;

const SPEAKER_COLOUR = { afterdream: '#E2EB98', you: '#EEF2C8' } as const;

type VoiceCaptionProps = {
  who: 'afterdream' | 'you';
  text: string;
  /** The line is still being spoken, so the words light up one at a time. Once it is over
   *  they are all lit, however far the reveal had got. */
  speaking: boolean;
  reduceMotion: boolean;
};

/**
 * The line being spoken right now, from the Afterdream Voice Agent design: who is talking,
 * then their words lighting up one by one. Afterdream's words wait at a third of full
 * brightness before they are said; yours only appear once they are heard.
 */
export function VoiceCaption({ who, text, speaking, reduceMotion }: VoiceCaptionProps) {
  const words = text.trim().split(/\s+/).filter(Boolean);
  const shown = useWordReveal(text, who, speaking, reduceMotion);

  return (
    <View style={styles.block} pointerEvents="none">
      <Animated.Text style={[styles.who, { color: SPEAKER_COLOUR[who] }]} accessibilityLiveRegion="polite">
        {who}
      </Animated.Text>
      <View style={styles.words}>
        {words.map((word, i) => (
          <Animated.Text
            key={`${i}-${word}`}
            style={[
              styles.word,
              { opacity: i < shown ? 1 : who === 'afterdream' ? 0.3 : 0 },
              ease(reduceMotion, ['opacity'], 250),
            ]}>
            {word}
          </Animated.Text>
        ))}
      </View>
    </View>
  );
}

/** Walks a counter up to the number of words, restarting whenever a new line arrives. */
function useWordReveal(text: string, who: 'afterdream' | 'you', speaking: boolean, reduceMotion: boolean) {
  const total = text.trim().split(/\s+/).filter(Boolean).length;
  const [shown, setShown] = useState(0);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  // A new line starts dark again. Keyed on the text itself, so a line that grows as more of
  // it is heard carries on from where it was instead of starting over.
  useEffect(() => {
    setShown(0);
  }, [who]);

  useEffect(() => {
    if (reduceMotion || !speaking) {
      setShown(total);
      return;
    }
    if (shown >= total) return;
    const step = who === 'afterdream' ? AFTERDREAM_MS : YOU_MS;
    timer.current = setTimeout(() => setShown((n) => n + 1), step);
    return () => {
      if (timer.current) clearTimeout(timer.current);
    };
  }, [shown, total, speaking, who, reduceMotion]);

  return shown;
}

const styles = StyleSheet.create({
  block: {
    height: CAPTION_HEIGHT,
    gap: 10,
    overflow: 'hidden',
  },
  who: {
    fontFamily: BrandFonts.semibold,
    fontSize: 11,
    lineHeight: 13,
    letterSpacing: 1.6,
    textTransform: 'uppercase',
  },
  words: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    columnGap: 6,
    rowGap: 2,
  },
  word: {
    fontFamily: BrandFonts.regular,
    fontSize: 23,
    lineHeight: 29,
    letterSpacing: -0.4,
    color: '#fff',
  },
});
