/** The pulsing dot in the timer pill (the design's `vDot`). */
const PULSE_DOT = { '0%': { opacity: 1 }, '50%': { opacity: 0.25 }, '100%': { opacity: 1 } };

/** Cycles the three loading lines while the dream is being read. */
function LoadingLine() {
  const [line, setLine] = useState(0);
  useEffect(() => {
    const timer = setInterval(() => setLine((n) => (n + 1) % LOADING_LINES.length), LINE_MS);
    return () => clearInterval(timer);
  }, []);
  return <>{LOADING_LINES[line]}</>;
}

/** Counts the conversation up from zero, for the pill in the top bar. */
function useCallSeconds(live: boolean) {
